mapper.select:
SELECT a.* FROM agent_profile a WHERE 
ORDER BY a.updated_at DESC, a.agent_id DESC
LIMIT #{pageable.pageSize} OFFSET #{pageable.offset}

SELECT agent_id, name, description, tenant_id, created_by, enabled, capability_bindings,
    created_at, updated_at FROM agent_profile
WHERE tenant_id = #{tenantId} AND created_by = #{ownerId} AND default_agent = false
AND agent_id != #{editingAgentId}
AND agent_id > #{after}

    AND (LOCATE(LOWER(#{query}), LOWER(COALESCE(name, ''))) > 0
        OR LOCATE(LOWER(#{query}), LOWER(COALESCE(description, ''))) > 0
        OR LOCATE(LOWER(#{query}), LOWER(CONCAT('agent:', agent_id))) > 0)

ORDER BY agent_id ASC LIMIT #{limit}
